from fastapi import FastAPI, Depends, Security, SecurityScopes
from fastapi.testclient import TestClient
import pytest

app = FastAPI()

def get_current_user(security_scopes: SecurityScopes):
    # This is the inner-most dependency. It should see all scopes.
    return security_scopes.scopes

def get_current_active_user(security_scopes: SecurityScopes, user=Depends(get_current_user)):
    # This is a middle dependency. It requires "me" scope.
    # But it also depends on get_current_user.
    # Wait, the example in docs says:
    # "Since the dependency `get_current_active_user` depends on `get_current_user`, 
    # the scope `"me"` declared at `get_current_active_user` is included in the list 
    # of required scopes in `security_scopes.scopes` passed to `get_current_user`."
    return user

@app.get("/test", dependencies=[Security(get_current_active_user, scopes=["me"])])
async def test_endpoint():
    return {"message": "ok"}

# Let's refine the repro to actually test the propagation.
# We need a dependency that uses SecurityScopes and is depended upon by another dependency that has scopes.

def inner_dep(security_scopes: SecurityScopes):
    return security_scopes.scopes

def outer_dep(scopes=Security(inner_dep, scopes=["outer_scope"])):
    return scopes

@app.get("/repro", dependencies=[Security(outer_dep, scopes=["root_scope"])])
async def repro_endpoint():
    return {"message": "ok"}

# Wait, the above is not quite right because outer_dep doesn't use SecurityScopes.
# Let's try:

def dep_c(security_scopes: SecurityScopes):
    # Should receive ["root_scope", "dep_b_scope"]
    return security_scopes.scopes

def dep_b(scopes=Security(dep_c, scopes=["dep_b_scope"])):
    return scopes

@app.get("/repro2", dependencies=[Security(dep_b, scopes=["root_scope"])])
async def repro2_endpoint():
    return {"message": "ok"}

# To test this, I need to actually call the dependency.
# Since dependencies are called by FastAPI, I can't easily check the return value of dep_c 
# unless I make it a path operation dependency or use a mock.

# Let's use a global variable to capture the scopes.
captured_scopes = []

def dep_c_capture(security_scopes: SecurityScopes):
    global captured_scopes
    captured_scopes = security_scopes.scopes
    return True

def dep_b_capture(scopes=Security(dep_c_capture, scopes=["dep_b_scope"])):
    return scopes

@app.get("/repro3", dependencies=[Security(dep_b_capture, scopes=["root_scope"])])
async def repro3_endpoint():
    return {"message": "ok"}

client = TestClient(app)

def test_scope_propagation():
    global captured_scopes
    captured_scopes = []
    response = client.get("/repro3")
    assert response.status_code == 200
    assert set(captured_scopes) == {"root_scope", "dep_b_scope"}, f"Expected {{'root_scope', 'dep_b_scope'}}, got {captured_scopes}"

if __name__ == "__main__":
    try:
        test_scope_propagation()
        print("Test passed!")
    except AssertionError as e:
        print(f"Test failed: {e}")
    except Exception as e:
        print(f"An error occurred: {e}")
        import traceback
        traceback.print_exc()
