from fastapi import FastAPI, Depends, Security
from fastapi.dependencies.utils import SecurityScopes
from fastapi.testclient import TestClient
import pytest

app = FastAPI()

captured_scopes = {}

def dep_leaf_1(security_scopes: SecurityScopes):
    captured_scopes["leaf_1"] = list(security_scopes.scopes)
    return True

def dep_leaf_2(security_scopes: SecurityScopes):
    captured_scopes["leaf_2"] = list(security_scopes.scopes)
    return True

def dep_branch_1(scopes=Security(dep_leaf_1, scopes=["branch_1_scope"])):
    return scopes

def dep_branch_2(scopes=Security(dep_leaf_2, scopes=["branch_2_scope"])):
    return scopes

@app.get("/leak")
async def leak_endpoint(
    b1=Security(dep_branch_1, scopes=["root_scope"]),
    b2=Security(dep_branch_2, scopes=["root_scope"])
):
